-- EarnBridge only: all objects are eb_-prefixed. Existing Garage tables are untouched.
create extension if not exists pgcrypto;
create table if not exists public.eb_profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',country text,city text,preferred_currency text not null default 'USD',headline text,bio text,website_url text,phone text,profile_visibility text not null default 'public' check(profile_visibility in('public','private')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.eb_skills(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,skill_name text not null,skill_level text not null default 'intermediate' check(skill_level in('beginner','intermediate','advanced','expert')),years_experience numeric(4,1) not null default 0,created_at timestamptz not null default now(),unique(user_id,skill_name));
create table if not exists public.eb_opportunities(id uuid primary key default gen_random_uuid(),created_by uuid references auth.users(id) on delete set null,title text not null,organization text,description text not null,opportunity_type text not null default 'project' check(opportunity_type in('job','freelance','project','contract','grant','research','partnership','other')),category text,country text,remote boolean not null default false,currency text not null default 'USD',budget_min numeric(14,2),budget_max numeric(14,2),application_url text,contact_email text,deadline date,source_url text,verification_status text not null default 'unverified' check(verification_status in('unverified','reviewing','verified','rejected')),status text not null default 'draft' check(status in('draft','published','closed','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.eb_saved_opportunities(user_id uuid not null references auth.users(id) on delete cascade,opportunity_id uuid not null references public.eb_opportunities(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,opportunity_id));
create table if not exists public.eb_applications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,opportunity_id uuid not null references public.eb_opportunities(id) on delete cascade,proposal text,proposed_amount numeric(14,2),currency text not null default 'USD',status text not null default 'draft' check(status in('draft','submitted','viewed','shortlisted','rejected','accepted','withdrawn')),submitted_at timestamptz,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,opportunity_id));
create table if not exists public.eb_businesses(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,business_name text not null,industry text,description text,website_url text,country text,city text,verification_status text not null default 'unverified' check(verification_status in('unverified','pending','verified','rejected')),created_at timestamptz not null default now());
create table if not exists public.eb_services(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,business_id uuid references public.eb_businesses(id) on delete set null,title text not null,category text,description text not null,delivery_days integer,price numeric(14,2),currency text not null default 'USD',pricing_type text not null default 'fixed' check(pricing_type in('fixed','hourly','starting_at','custom')),status text not null default 'draft' check(status in('draft','published','paused','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.eb_customer_leads(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,contact_name text not null,company text,email text,phone text,country text,source text,need_description text,estimated_value numeric(14,2),currency text not null default 'USD',stage text not null default 'new' check(stage in('new','contacted','qualified','proposal_sent','won','lost')),next_follow_up date,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.eb_enquiries(id uuid primary key default gen_random_uuid(),service_id uuid not null references public.eb_services(id) on delete cascade,provider_id uuid not null references auth.users(id) on delete cascade,customer_id uuid not null references auth.users(id) on delete cascade,message text not null,budget numeric(14,2),currency text not null default 'USD',status text not null default 'new' check(status in('new','replied','converted','declined','closed')),created_at timestamptz not null default now(),check(provider_id<>customer_id));
create table if not exists public.eb_orders(id uuid primary key default gen_random_uuid(),service_id uuid references public.eb_services(id) on delete set null,provider_id uuid not null references auth.users(id) on delete cascade,customer_id uuid not null references auth.users(id) on delete cascade,title text not null,description text,amount numeric(14,2) not null default 0,currency text not null default 'USD',status text not null default 'requested' check(status in('requested','accepted','in_progress','delivered','completed','cancelled','disputed')),due_date date,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(provider_id<>customer_id));
create table if not exists public.eb_earnings(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,order_id uuid references public.eb_orders(id) on delete set null,description text not null,amount numeric(14,2) not null,currency text not null default 'USD',earning_date date not null default current_date,payment_status text not null default 'pending' check(payment_status in('pending','received','refunded','cancelled')),external_reference text,created_at timestamptz not null default now());
create table if not exists public.eb_ai_usage(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,feature text not null,credits_used integer not null default 0 check(credits_used>=0),created_at timestamptz not null default now());
create table if not exists public.eb_subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,plan_code text not null default 'free' check(plan_code in('free','pro','business')),status text not null default 'inactive' check(status in('inactive','trialing','active','past_due','cancelled','expired')),provider text,provider_customer_id text,provider_subscription_id text,current_period_start timestamptz,current_period_end timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.eb_payments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,subscription_id uuid references public.eb_subscriptions(id) on delete set null,amount numeric(14,2) not null,currency text not null default 'USD',provider text,provider_reference text,status text not null default 'pending' check(status in('pending','succeeded','failed','refunded')),created_at timestamptz not null default now());
create table if not exists public.eb_reviews(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.eb_orders(id) on delete cascade,reviewer_id uuid not null references auth.users(id) on delete cascade,reviewee_id uuid not null references auth.users(id) on delete cascade,rating integer not null check(rating between 1 and 5),comment text,created_at timestamptz not null default now(),unique(order_id,reviewer_id),check(reviewer_id<>reviewee_id));
create table if not exists public.eb_notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,body text not null,notification_type text not null default 'general',read_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.eb_reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references auth.users(id) on delete cascade,target_type text not null,target_id uuid not null,reason text not null,details text,status text not null default 'open' check(status in('open','reviewing','resolved','dismissed')),created_at timestamptz not null default now());

create index if not exists eb_opportunities_public_idx on public.eb_opportunities(status,created_at desc);
create index if not exists eb_services_public_idx on public.eb_services(status,created_at desc);
create index if not exists eb_leads_owner_idx on public.eb_customer_leads(owner_id,stage);
create index if not exists eb_earnings_owner_idx on public.eb_earnings(user_id,earning_date desc);

-- RLS on every EarnBridge table.
alter table public.eb_profiles enable row level security; alter table public.eb_skills enable row level security; alter table public.eb_opportunities enable row level security; alter table public.eb_saved_opportunities enable row level security; alter table public.eb_applications enable row level security; alter table public.eb_businesses enable row level security; alter table public.eb_services enable row level security; alter table public.eb_customer_leads enable row level security; alter table public.eb_enquiries enable row level security; alter table public.eb_orders enable row level security; alter table public.eb_earnings enable row level security; alter table public.eb_ai_usage enable row level security; alter table public.eb_subscriptions enable row level security; alter table public.eb_payments enable row level security; alter table public.eb_reviews enable row level security; alter table public.eb_notifications enable row level security; alter table public.eb_reports enable row level security;

create policy eb_profile_select on public.eb_profiles for select to authenticated using(profile_visibility='public' or id=auth.uid());
create policy eb_profile_insert on public.eb_profiles for insert to authenticated with check(id=auth.uid());
create policy eb_profile_update on public.eb_profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy eb_skills_owner on public.eb_skills for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy eb_opportunities_public on public.eb_opportunities for select to anon,authenticated using(status='published');
create policy eb_opportunities_owner_select on public.eb_opportunities for select to authenticated using(created_by=auth.uid());
create policy eb_opportunities_owner_insert on public.eb_opportunities for insert to authenticated with check(created_by=auth.uid());
create policy eb_opportunities_owner_update on public.eb_opportunities for update to authenticated using(created_by=auth.uid()) with check(created_by=auth.uid());
create policy eb_opportunities_owner_delete on public.eb_opportunities for delete to authenticated using(created_by=auth.uid());
create policy eb_saved_owner on public.eb_saved_opportunities for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy eb_applications_owner on public.eb_applications for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy eb_business_owner on public.eb_businesses for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy eb_services_public on public.eb_services for select to anon,authenticated using(status='published');
create policy eb_services_owner_select on public.eb_services for select to authenticated using(user_id=auth.uid());
create policy eb_services_owner_insert on public.eb_services for insert to authenticated with check(user_id=auth.uid());
create policy eb_services_owner_update on public.eb_services for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy eb_services_owner_delete on public.eb_services for delete to authenticated using(user_id=auth.uid());
create policy eb_leads_owner on public.eb_customer_leads for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy eb_enquiries_participant_select on public.eb_enquiries for select to authenticated using(provider_id=auth.uid() or customer_id=auth.uid());
create policy eb_enquiries_customer_insert on public.eb_enquiries for insert to authenticated with check(customer_id=auth.uid());
create policy eb_enquiries_provider_update on public.eb_enquiries for update to authenticated using(provider_id=auth.uid()) with check(provider_id=auth.uid());
create policy eb_orders_participant_select on public.eb_orders for select to authenticated using(provider_id=auth.uid() or customer_id=auth.uid());
create policy eb_orders_customer_insert on public.eb_orders for insert to authenticated with check(customer_id=auth.uid());
create policy eb_orders_participant_update on public.eb_orders for update to authenticated using(provider_id=auth.uid() or customer_id=auth.uid()) with check(provider_id=auth.uid() or customer_id=auth.uid());
create policy eb_earnings_owner on public.eb_earnings for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy eb_ai_usage_owner on public.eb_ai_usage for select to authenticated using(user_id=auth.uid());
create policy eb_subscriptions_owner on public.eb_subscriptions for select to authenticated using(user_id=auth.uid());
create policy eb_payments_owner on public.eb_payments for select to authenticated using(user_id=auth.uid());
create policy eb_reviews_select on public.eb_reviews for select to authenticated using(true);
create policy eb_reviews_insert on public.eb_reviews for insert to authenticated with check(reviewer_id=auth.uid());
create policy eb_notifications_owner on public.eb_notifications for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy eb_reports_insert on public.eb_reports for insert to authenticated with check(reporter_id=auth.uid());
create policy eb_reports_select on public.eb_reports for select to authenticated using(reporter_id=auth.uid());

grant usage on schema public to anon,authenticated;
grant select on public.eb_opportunities,public.eb_services to anon,authenticated;
grant select,insert,update,delete on public.eb_profiles,public.eb_skills,public.eb_saved_opportunities,public.eb_applications,public.eb_businesses,public.eb_customer_leads,public.eb_enquiries,public.eb_orders,public.eb_earnings,public.eb_ai_usage,public.eb_subscriptions,public.eb_payments,public.eb_reviews,public.eb_notifications,public.eb_reports to authenticated;
